import sys
import traceback


def _test(expected, actual, call):
    try:
        assert actual == expected, "{} should return {}. Your code: {}".format(call, expected, actual)
        print("\u2713 passed: {} \u2192 {}".format(call, expected))
    except AssertionError as ae:
        print("\u2717 failed: {}".format(ae))


class HashMapTests:

    def __init__(self, module_name):
        self.module = module_name

    def test_01_set_and_get(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            hm = self.module.HashMap()
            hm["a"] = 1
            hm["b"] = 2
            hm["c"] = 3

            _test(expected=1,
                  actual=hm["a"],
                  call='hm["a"]')

            _test(expected=2,
                  actual=hm["b"],
                  call='hm["b"]')

            _test(expected=3,
                  actual=hm["c"],
                  call='hm["c"]')
        except Exception as e:
            print("\u2717 FAILED. basic set/get raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_02_overwrite_value(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            hm = self.module.HashMap()
            hm["x"] = 10
            hm["x"] = 20

            _test(expected=20,
                  actual=hm["x"],
                  call='hm["x"] after overwrite')
        except Exception as e:
            print("\u2717 FAILED. overwriting value raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_03_contains(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            hm = self.module.HashMap()
            hm["foo"] = 42

            _test(expected=True,
                  actual=("foo" in hm),
                  call='"foo" in hm')

            _test(expected=False,
                  actual=("bar" in hm),
                  call='"bar" in hm')
        except Exception as e:
            print("\u2717 FAILED. __contains__ raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_04_getitem_key_error(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            hm = self.module.HashMap()
            hm["a"] = 1
            try:
                _ = hm["missing"]
                print("\u2717 FAILED. __getitem__ did not raise KeyError for missing key")
            except KeyError:
                print("\u2713 passed: __getitem__ raised KeyError for missing key")
        except Exception as e:
            print("\u2717 FAILED. calling __getitem__ raised an unexpected exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_05_delete_existing_key(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            hm = self.module.HashMap()
            hm["a"] = 1
            hm["b"] = 2
            del hm["a"]

            _test(expected=False,
                  actual=("a" in hm),
                  call='"a" in hm after delete')

            try:
                _ = hm["a"]
                print("\u2717 FAILED. deleted key still accessible via __getitem__")
            except KeyError:
                print("\u2713 passed: deleted key raises KeyError on __getitem__")
        except Exception as e:
            print("\u2717 FAILED. deleting existing key raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_06_delete_missing_key_error(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            hm = self.module.HashMap()
            hm["a"] = 1
            try:
                del hm["missing"]
                print("\u2717 FAILED. __delitem__ did not raise KeyError for missing key")
            except KeyError:
                print("\u2713 passed: __delitem__ raised KeyError for missing key")
        except Exception as e:
            print("\u2717 FAILED. deleting missing key raised an unexpected exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_07_get_keys_content(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            hm = self.module.HashMap()
            hm["a"] = 1
            hm["b"] = 2
            hm["c"] = 3

            keys = hm.get_keys()
            # order is insertion order because you append on first insert
            _test(expected=["a", "b", "c"],
                  actual=keys,
                  call="hm.get_keys() after inserts")

            del hm["b"]
            keys_after_delete = hm.get_keys()
            _test(expected=["a", "c"],
                  actual=keys_after_delete,
                  call="hm.get_keys() after deleting 'b'")
        except Exception as e:
            print("\u2717 FAILED. get_keys tests raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_08_collision_handling(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            # Force many keys into a small table to encourage collisions
            hm = self.module.HashMap(size=1)
            hm["a"] = 1
            hm["b"] = 2
            hm["c"] = 3

            _test(expected=1,
                  actual=hm["a"],
                  call='hm["a"] in collision table')

            _test(expected=2,
                  actual=hm["b"],
                  call='hm["b"] in collision table')

            _test(expected=3,
                  actual=hm["c"],
                  call='hm["c"] in collision table')

            del hm["b"]
            try:
                _ = hm["b"]
                print("\u2717 FAILED. deleted key in collision chain still accessible")
            except KeyError:
                print("\u2713 passed: deleted key in collision chain raises KeyError")
        except Exception as e:
            print("\u2717 FAILED. collision handling tests raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_all(self):
        self.test_01_set_and_get()
        self.test_02_overwrite_value()
        self.test_03_contains()
        self.test_04_getitem_key_error()
        self.test_05_delete_existing_key()
        self.test_06_delete_missing_key_error()
        self.test_07_get_keys_content()
        self.test_08_collision_handling()
